import React from 'react';
import { SolutionResponse } from '../../types';

interface ResultsDisplayProps {
    result: SolutionResponse;
}

export const ResultsDisplay: React.FC<ResultsDisplayProps> = ({ result }) => {
    // Форматирование чисел для строгого вывода
    const formatNumber = (value: number): string => {
        if (value === 0) return "0.0";
        // Для очень маленьких чисел используем экспоненциальную форму
        if (Math.abs(value) < 1e-7) return value.toExponential(4);
        // Для обычных чисел до 10 знаков, убираем лишние нули в конце
        return value.toFixed(10).replace(/\.?0+$/, '');
    };

    return (
        <div className="space-y-8 font-mono text-slate-900">
            {/* Верхняя строка: Статус и ключевые показатели */}
            <div className="border-t border-b border-slate-900 py-4 grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                    <span className="text-[10px] font-bold uppercase text-slate-400 block mb-1">Status</span>
                    <div className="text-sm font-bold uppercase tracking-tight">
                        {result.diagonalDominance
                            ? '[✓] Diagonal Dominance: OK'
                            : '[!] Diagonal Dominance: ABSENT'}
                    </div>
                </div>
                <div className="md:text-right">
                    <span className="text-[10px] font-bold uppercase text-slate-400 block mb-1">Iterations</span>
                    <div className="text-xl font-bold">{result.iterations}</div>
                </div>
            </div>

            {/* Сетка характеристик */}
            <div className="grid grid-cols-2 gap-px bg-slate-200 border border-slate-200">
                <div className="bg-white p-4">
                    <span className="text-[10px] font-bold uppercase text-slate-400 block mb-1">Determinant</span>
                    <div className="text-lg font-bold">{formatNumber(result.determinant)}</div>
                </div>
                <div className="bg-white p-4">
                    <span className="text-[10px] font-bold uppercase text-slate-400 block mb-1">Matrix Norm</span>
                    <div className="text-lg font-bold">{formatNumber(result.matrixNorm)}</div>
                </div>
            </div>

            {/* Векторы решения и невязки (Табличный вид для дробных чисел) */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                {/* Решение X */}
                <div className="space-y-3">
                    <h3 className="text-xs font-bold uppercase tracking-widest text-slate-500 border-l-2 border-slate-900 pl-2">
                        Solution Vector (X)
                    </h3>
                    <div className="border border-slate-200">
                        <table className="w-full text-xs text-left">
                            <thead className="bg-slate-50 border-b border-slate-200">
                            <tr>
                                <th className="px-3 py-2 font-bold text-slate-400 w-12">#</th>
                                <th className="px-3 py-2 font-bold">Value</th>
                            </tr>
                            </thead>
                            <tbody className="divide-y divide-slate-100">
                            {result.solution.map((value, index) => (
                                <tr key={index}>
                                    <td className="px-3 py-2 text-slate-300 border-r border-slate-100">{index + 1}</td>
                                    <td className="px-3 py-2 font-bold">{formatNumber(value)}</td>
                                </tr>
                            ))}
                            </tbody>
                        </table>
                    </div>
                </div>

                {/* Невязка R */}
                <div className="space-y-3">
                    <h3 className="text-xs font-bold uppercase tracking-widest text-slate-500 border-l-2 border-slate-200 pl-2">
                        Residual Vector (R)
                    </h3>
                    <div className="border border-slate-200">
                        <table className="w-full text-xs text-left">
                            <thead className="bg-slate-50 border-b border-slate-200">
                            <tr>
                                <th className="px-3 py-2 font-bold text-slate-400 w-12">#</th>
                                <th className="px-3 py-2 font-bold">Error (Ax-b)</th>
                            </tr>
                            </thead>
                            <tbody className="divide-y divide-slate-100 text-slate-500">
                            {result.residual.map((value, index) => (
                                <tr key={index}>
                                    <td className="px-3 py-2 border-r border-slate-100">{index + 1}</td>
                                    <td className="px-3 py-2">{formatNumber(value)}</td>
                                </tr>
                            ))}
                            </tbody>
                        </table>
                    </div>
                </div>
            </div>

            {/* Сообщение о сходимости */}
            <div className="p-4 border border-slate-900 text-xs leading-relaxed">
                <div className="font-bold uppercase mb-1">Execution Summary:</div>
                <p className="mb-2">{result.message}</p>
                {result.iterationHistory && result.iterationHistory.length > 0 && (
                    <div className="text-slate-400">
                        Last iteration error (max|xi^k - xi^k-1|):
                        <span className="text-slate-900 ml-2 font-bold">
                            {formatNumber(result.iterationHistory[result.iterationHistory.length - 1].maxError)}
                        </span>
                    </div>
                )}
            </div>
        </div>
    );
};
